Graph.__index = Graph
local STATE_PROPERTIES = {"Visible", "Enabled", "Text", "Active", "Interactable",
    "Selected", "Selectable", "TextEditable", "ScrollingEnabled", "Playing"}

function Gui.new(cfg, context)
    cfg = cfg or {}
